// @vegastack chip-input@0.23.4 sha256-vwDCH3JLO2hdCDxC6n9nL2Xo6H6DqCRaNLvtDq482Vs=

"use client";

import * as React from "react";
import { cn, mergeRefs } from "@vegastack/design";
import { InputGroup, InputGroupInput } from "@/components/ui/input-group";
import { Tag } from "@/components/ui/tag-group";
import { useAnnouncer } from "@/components/ui/use-announcer";

/* ---
`ChipInput` exists because nothing in the roster can commit an arbitrary token:
`TagGroup` is a display list with no input, and Base UI's Combobox value model is
selection-from-items — there is no create seam. Domains, e-mail recipients, tags,
webhook events all need "type, Enter/comma/paste, chip".

The field chrome is upstream's `InputGroup`, imported rather than restated: border,
focus border, invalid hairline, disabled wash and the dark-mode fill are all its own, and
the inner control is `InputGroupInput`, which is upstream `Input` flattened into the box.
What stays local is the one thing upstream has no counterpart for — a field whose content
WRAPS, so the box grows with the chips instead of holding a single 32px line. The chip is
the real `Tag`, which already ships `onRemove` and a compliant 24px hit area.

Validation model: entries are ADDED and marked, not silently dropped. A pasted list of
20 addresses with 2 typos should show 20 chips with 2 flagged for fixing — a per-chip
`data-invalid` (the one channel `Tag`/`Combobox` lack) — while duplicates are the only
rejected class. Accepted/invalid/duplicate outcomes are announced politely.

Deliberately NOT done here:
- No suggestion popup. An autocomplete-backed chip field is a Combobox composition, not
  this component — building it in would re-implement filtering Base UI already owns.
- No TagGroup re-export. Its `max`/`+N` collapse is display-list semantics; an editable
  field must keep every chip reachable.
- No hue prop on chips. `Tag` hue is decorative labelling, never status — invalid is the
  only state a chip carries here, and it is not a colour alone (border + description).
--- */

/**
 * The wrapping layout, and nothing else: upstream's `InputGroup` is a single-line box
 * (`h-8`, `items-center`), and a chip field is a growing one. Height becomes `auto` over a
 * one-line floor, children wrap, and the inner `InputGroupInput` keeps a 24px minimum box —
 * a replaced element cannot host a `::before` hit area, so its own box must meet the pointer
 * floor (A11Y-2). Every colour, border and state in the box is `InputGroup`'s.
 */
const chipFieldLayout = [
  "h-auto min-h-8 flex-wrap items-center gap-1 p-1",
  "[&_[data-slot=input-group-control]]:h-full [&_[data-slot=input-group-control]]:min-h-6 [&_[data-slot=input-group-control]]:min-w-12 [&_[data-slot=input-group-control]]:flex-1 [&_[data-slot=input-group-control]]:px-1.5 [&_[data-slot=input-group-control]]:py-0",
].join(" ");

/** Props accepted by `ChipInput`. */
export interface ChipInputProps {
  /** Controlled chip list. Pair with `onValueChange`; omit for uncontrolled use.
   * @default undefined
   */
  value?: string[];
  /**
   * Initial chips for uncontrolled use.
   * @default []
   */
  defaultValue?: string[];
  /** Fired with the next chip list on every add or remove.
   * @default undefined
   */
  onValueChange?: (value: string[]) => void;
  /**
   * Normalise a raw entry before it is committed (and before duplicate
   * checking). The default trims whitespace.
   * @default (raw) => raw.trim()
   */
  normalize?: (raw: string) => string;
  /**
   * Per-chip validity. Invalid entries are still **added**, marked with
   * `data-invalid` on their chip, described as invalid for assistive tech, and
   * flip the whole field invalid until fixed or removed —
   * a pasted list keeps every entry visible instead of silently dropping the
   * malformed ones.

   * @default undefined
   */
  validate?: (chip: string) => boolean;
  /**
   * Pattern the paste handler splits on, in addition to the Enter/comma commit
   * keys.
   * @default /[,\n]/
   */
  splitOn?: RegExp;
  /**
   * Allow the same chip twice. When `false`, a duplicate entry is rejected and
   * announced.
   * @default false
   */
  allowDuplicates?: boolean;
  /** Placeholder for the inner input while the field has room.
   * @default undefined
   */
  placeholder?: string;
  /** Accessible name for the inner input. Inside a `Field` the `FieldLabel` names it; standalone,
   * the control must never be unnamed.
   * @default undefined
   */
  "aria-label"?: string;
  /**
   * Submits every chip with a surrounding `<form>` under this name — one value per chip, the way
   * a multi-select posts.
   * @default undefined
   */
  name?: string;
  /**
   * The most chips the field accepts. At the cap, further entries are not added and the reason is
   * announced.
   * @default undefined
   */
  max?: number;
  /**
   * The copy announced when an entry is refused at `max`.
   * @default (max) => `Up to ${max} entries`
   */
  maxLabel?: (max: number) => string;
  /**
   * Disables the field and every chip's remove button.
   * @default false
   */
  disabled?: boolean;
  /** Extra classes for the field group root.
   * @default undefined
   */
  className?: string;
  /**
   * Ref forwarded to the group root `<div>` (`data-slot="chip-input"`).

   * @default undefined
   */
  ref?: React.Ref<HTMLDivElement>;
  /**
   * Ref forwarded to the inner `<input>`.

   * @default undefined
   */
  inputRef?: React.Ref<HTMLInputElement>;
}

const defaultNormalize = (raw: string) => raw.trim();
const defaultMaxLabel = (max: number) => `Up to ${max} entries`;
const DEFAULT_SPLIT = /[,\n]/;

/**
 * `ChipInput` — free-token entry: type, then <kbd>Enter</kbd> or comma to
 * commit a chip; paste splits on the same delimiters; <kbd>Backspace</kbd> in
 * the empty input removes the last chip. The box is upstream's `InputGroup`, grown
 * to wrap; the chips are real `Tag`s (24px remove targets included); and validation
 * is per-chip — invalid entries stay visible with `data-invalid` instead of being
 * silently dropped.
 *
 * @example
 * const [emails, setEmails] = React.useState<string[]>([]);
 * <ChipInput
 *   aria-label="Recipients"
 *   value={emails}
 *   onValueChange={setEmails}
 *   validate={(chip) => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(chip)}
 *   placeholder="Add recipients…"
 * />
 */
export function ChipInput({
  value: controlledValue,
  defaultValue = [],
  onValueChange,
  normalize = defaultNormalize,
  validate,
  splitOn = DEFAULT_SPLIT,
  allowDuplicates = false,
  placeholder,
  "aria-label": ariaLabel,
  name,
  max,
  maxLabel = defaultMaxLabel,
  disabled = false,
  className,
  ref,
  inputRef,
}: ChipInputProps) {
  // Chip list — controlled when `value` is provided, else internal.
  const [internalValue, setInternalValue] = React.useState(defaultValue);
  const isControlled = controlledValue !== undefined;
  const chips = isControlled ? controlledValue : internalValue;
  const [draft, setDraft] = React.useState("");
  // One announcer, one policy, one live region — `use-announcer` owns the
  // sequence keying that makes an IDENTICAL consecutive announcement (a second
  // rejected duplicate) mutate the DOM and re-announce.
  const { announce: setAnnouncement, Announcer } = useAnnouncer();
  const describeId = React.useId();

  const commitValue = React.useCallback(
    (next: string[]) => {
      if (!isControlled) setInternalValue(next);
      onValueChange?.(next);
    },
    [isControlled, onValueChange],
  );

  const isInvalidChip = React.useCallback(
    (chip: string) => (validate ? !validate(chip) : false),
    [validate],
  );
  const hasInvalidChip = chips.some(isInvalidChip);

  // The reject/invalid cue is the group border flipping destructive via `data-invalid`. The
  // shake that used to accompany it is gone from here: validation MOTION belongs to `Field`,
  // which owns it once for every control it wraps (audit D5). A ChipInput inside a `<Field
  // error=…>` still shakes; a per-chip rejection is a border + a text description, which is
  // the non-destructive contract this component already documents.
  // Removing a chip via its own button unmounts the focused element — return
  // focus to the field's input instead of letting it fall to <body>.
  const internalInputRef = React.useRef<HTMLInputElement | null>(null);
  const mergedInputRef = React.useMemo(
    () => mergeRefs(inputRef, internalInputRef),
    [inputRef],
  );

  /** Commit one or more raw entries (typed or pasted). */
  const addEntries = React.useCallback(
    (raws: string[]) => {
      const next = [...chips];
      let added = 0;
      let invalid = 0;
      let duplicates = 0;
      let overMax = 0;
      for (const raw of raws) {
        const chip = normalize(raw);
        if (chip.length === 0) continue;
        if (!allowDuplicates && next.includes(chip)) {
          duplicates += 1;
          continue;
        }
        if (max !== undefined && next.length >= max) {
          overMax += 1;
          continue;
        }
        next.push(chip);
        added += 1;
        if (isInvalidChip(chip)) invalid += 1;
      }
      if (added > 0) commitValue(next);
      // Voice: sentence case, no "successfully", counts only when they inform.
      const parts: string[] = [];
      if (added > 0)
        parts.push(
          added === 1
            ? `Added ${next[next.length - 1]}`
            : `Added ${added} entries`,
        );
      if (invalid > 0)
        parts.push(
          invalid === 1
            ? "1 entry is invalid"
            : `${invalid} entries are invalid`,
        );
      if (duplicates > 0)
        parts.push(
          duplicates === 1
            ? "1 duplicate skipped"
            : `${duplicates} duplicates skipped`,
        );
      if (overMax > 0 && max !== undefined) parts.push(maxLabel(max));
      if (parts.length > 0) setAnnouncement(parts.join(" · "));
      // A refused entry at the cap stays in the input, so nothing typed is lost.
      return added > 0 || duplicates > 0;
    },
    [
      chips,
      normalize,
      allowDuplicates,
      max,
      maxLabel,
      isInvalidChip,
      commitValue,
      setAnnouncement,
    ],
  );

  const removeChip = React.useCallback(
    (index: number) => {
      const removed = chips[index];
      const next = chips.filter((_, i) => i !== index);
      commitValue(next);
      if (removed != null) setAnnouncement(`Removed ${removed}`);
      internalInputRef.current?.focus();
    },
    [chips, commitValue, setAnnouncement],
  );

  const commitDraft = React.useCallback(() => {
    if (draft.trim().length === 0) return;
    if (addEntries(draft.split(splitOn))) setDraft("");
  }, [draft, addEntries, splitOn]);

  return (
    <InputGroup
      ref={ref}
      data-slot="chip-input"
      data-field-group=""
      data-invalid={hasInvalidChip ? "" : undefined}
      data-disabled={disabled ? "" : undefined}
      className={cn(chipFieldLayout, className)}
    >
      {chips.map((chip, index) => {
        const invalid = isInvalidChip(chip);
        return (
          <Tag
            // Duplicate chips are only possible with `allowDuplicates` — key by
            // position then, identity otherwise.
            key={allowDuplicates ? `${chip}-${index}` : chip}
            data-invalid={invalid ? "" : undefined}
            className={cn(
              invalid && "border-destructive/50 text-destructive-text",
            )}
            onRemove={disabled ? undefined : () => removeChip(index)}
            removeLabel={`Remove ${chip}`}
          >
            {chip}
            {invalid ? (
              // Real text in the accessible name — aria-description is an
              // ARIA 1.3 draft with no shipped AT support.
              <span className="sr-only">, invalid entry</span>
            ) : null}
          </Tag>
        );
      })}
      <InputGroupInput
        ref={mergedInputRef}
        aria-label={ariaLabel}
        aria-describedby={hasInvalidChip ? describeId : undefined}
        aria-invalid={hasInvalidChip || undefined}
        placeholder={chips.length === 0 ? placeholder : undefined}
        disabled={disabled}
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={(event) => {
          // Never commit mid-IME-composition — Enter there accepts the
          // candidate, not the chip.
          if (event.nativeEvent.isComposing) return;
          if (event.key === "Enter" || event.key === ",") {
            event.preventDefault();
            commitDraft();
          } else if (
            event.key === "Backspace" &&
            draft.length === 0 &&
            chips.length > 0
          ) {
            event.preventDefault();
            removeChip(chips.length - 1);
          }
        }}
        onBlur={commitDraft}
        onPaste={(event) => {
          const text = event.clipboardData.getData("text");
          // `split`, never `.test()` — a caller-supplied /g regex would make
          // `test` stateful and silently drop alternate pastes.
          const parts = text.split(splitOn);
          if (parts.length < 2) return;
          event.preventDefault();
          addEntries(parts);
        }}
      />
      {/* DS-21: the form value — one hidden input per chip under `name`. */}
      {name
        ? chips.map((chip, index) => (
            <input
              key={`${chip}-${index}`}
              type="hidden"
              name={name}
              value={chip}
            />
          ))
        : null}
      {/* Static description target — separate from the live region so the
          field's description never carries stale transient announcements. */}
      <span id={describeId} className="sr-only">
        Some entries are invalid
      </span>
      <Announcer />
    </InputGroup>
  );
}
